import {escapeHTML as e,imageURL,imageFile} from './store.js';
const defaults={title:'Seu universo começa aqui.',intro:'Dê espaço às suas ideias. O extraordinário está nos detalhes.',bannerTitle:'Imagine sem limites.\nCrie com propósito.',bannerText:'Dos primeiros esboços aos reinos mais distantes.\nCada ideia tem um lugar no seu universo.',cover:'assets/castle.jpg',quote:'Não são todos os que vagueiam que estão perdidos.',author:'J. R. R. Tolkien',hero:true,stats:true,recent:true,map:true,inspiration:true,shortcuts:true};
export const overviewSettings=w=>({...defaults,...w.overview,cover:imageURL(w.overview?.cover)||defaults.cover});
export function renderOverview(w,counts,heading,btn){const o=overviewSettings(w),recent=[...w.notes].sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,3);return `<div class="page overview-page">${heading('CADA GRANDE HISTÓRIA COMEÇA COM UM MUNDO.',e(o.title),e(o.intro),btn('⚙ Personalizar','customizeOverview','ghost'))}${o.hero?`<section class="hero"><img src="${o.cover}" alt="Capa do seu universo" fetchpriority="high"><div class="hero-content"><span class="eyebrow">${e(w.name)}</span><h2>${e(o.bannerTitle).replaceAll('\n','<br>')}</h2><p>${e(o.bannerText).replaceAll('\n','<br>')}</p>${btn('Continue sua história ↗','continue','light')}</div><span class="hero-bottom">UM LUGAR PARA O IMPOSSÍVEL EXISTIR ✧</span></section>`:''}${o.stats?`<div class="stats">${[['notes','▤','Documentos'],['characters','♙','Personagens'],['maps','♧','Mapas'],['bestiary','♧','Criaturas']].filter(([key])=>w.enabled.includes(key)).map(([key,icon,label])=>`<button class="stat" data-view="${key}"><span class="stat-icon">${icon}</span><span><strong>${String(counts[key]).padStart(2,'0')}</strong><small>${label} no seu mundo</small></span></button>`).join('')}</div>`:''}<div class="dashboard-columns ${(o.recent&&o.map&&w.enabled.includes('maps'))?'':'single-column'}">${o.recent?`<section><div class="section-heading"><h2>Onde a história parou</h2><button class="text-link" data-view="notes">Abrir notas ↗</button></div><div class="recent-list">${recent.length?recent.map(n=>`<button class="recent-row" data-note="${n.id}"><span class="document-icon">▤</span><div><h3>${e(n.title)}</h3><p>Notas & documentos</p></div><small>Continuar ↗</small></button>`).join(''):`<div class="empty"><p>Uma página para a sua próxima ideia.</p>${btn('＋ Criar documento','note')}</div>`}</div></section>`:''}${o.map&&w.enabled.includes('maps')?`<section><div class="section-heading"><h2>Um mundo a explorar</h2><button class="text-link" data-view="maps">Abrir atlas ↗</button></div><button class="map-preview" data-view="maps" style="width:100%;padding:0"><img src="${imageURL(w.maps[0]?.image)||'assets/eldoria.svg'}" alt="Mapa do seu universo"><span class="map-preview-info"><strong>${e(w.maps[0]?.name||'Seu atlas de mundos')}</strong><small>${w.maps.reduce((n,m)=>n+m.pins.length,0)} regiões descobertas · Atlas do universo</small></span></button></section>`:''}</div>${o.inspiration?`<div class="quote">“${e(o.quote)}”<small>${e(o.author)}</small></div>`:''}${o.shortcuts?`<section class="explore-section"><div class="section-heading"><h2>Expanda seu imaginário</h2><span class="eyebrow">DÊ VIDA AO QUE AINDA NÃO EXISTE</span></div><div class="explore-grid">${[['characters','♙','Quem habita seu mundo?','Crie personagens com histórias.'],['globe','◎','Uma nova perspectiva','Explore seu universo em 3D.'],['plot','⌘','Conecte os acontecimentos','Transforme ideias em enredo.']].filter(([key])=>w.enabled.includes(key)).map(([key,icon,title,desc])=>`<button class="explore-card" data-view="${key}"><span>${icon}</span><div><h3>${title}</h3><p>${desc}</p></div><b>↗</b></button>`).join('')}</div></section>`:''}</div>`;}
export function customizeOverview(w,modal,field,onSave){const o=overviewSettings(w);modal('Seu jeito de imaginar',field('Título da visão geral','title',o.title)+field('Introdução','intro',o.intro)+field('Título da capa','bannerTitle',o.bannerTitle,'textarea')+field('Descrição da capa','bannerText',o.bannerText,'textarea')+'<label class="field"><span>Imagem de capa (opcional)</span><input name="cover" type="file" accept="image/*"></label><label class="help"><input type="checkbox" name="resetCover" style="width:auto"> Restaurar a imagem de capa original</label>'+field('Citação','quote',o.quote,'textarea')+field('Autor da citação','author',o.author)+'<h3 style="margin:22px 0 10px">O que você quer ver?</h3>'+[['hero','Capa do universo'],['stats','Contadores'],['recent','Documentos recentes'],['map','Mapa em destaque'],['inspiration','Citação'],['shortcuts','Atalhos criativos']].map(([key,label])=>`<label class="overview-toggle"><span>${label}</span><input type="checkbox" name="${key}" ${o[key]?'checked':''}></label>`).join(''),async data=>{const next={};for(const key of ['title','intro','bannerTitle','bannerText','quote','author'])next[key]=String(data.get(key)||'').trim().slice(0,1000);for(const key of ['hero','stats','recent','map','inspiration','shortcuts'])next[key]=data.has(key);next.cover=data.has('resetCover')?defaults.cover:o.cover;if(data.get('cover')?.size)next.cover=await imageFile(data.get('cover'));w.overview=next;onSave();});}
